package com.example.model

enum class BattlePhase {
    PLAYER_TURN,
    ANIMATING_ACTION,
    AI_TURN,
    VICTORY,
    DEFEAT
}

data class CombatLogEntry(
    val turn: Int,
    val message: String,
    val formula: String? = null,
    val isCrit: Boolean = false,
    val isPlayerAction: Boolean = true
)

/**
 * Resonant barrier generated by enemy commander or elite node
 */
data class EigenBarrier(
    val matrix: Matrix2x2,
    val resonantAngleDeg: Float, // Direction of eigenvector: attack aligned here gets 3x crit!
    val shieldIntegrity: Int,
    val maxIntegrity: Int
)

data class BattleState(
    val gridWidth: Int = 10,
    val gridHeight: Int = 10,
    val cells: Map<GridPos, FieldCell> = emptyMap(),
    val units: List<TacticalUnit> = emptyList(),
    val turnNumber: Int = 1,
    val phase: BattlePhase = BattlePhase.PLAYER_TURN,
    val playerEnergy: Int = 80,
    val maxPlayerEnergy: Int = 100,
    val playerActionPoints: Int = 3,
    val maxActionPoints: Int = 3,
    val aiEnergy: Int = 50,
    val selectedUnitId: String? = null,
    val selectedAbility: TacticalAbility? = null,
    val selectedPivot: GridPos? = null,
    val targetCell: GridPos? = null,
    val transformationPreview: Map<String, GridPos> = emptyMap(),
    val ricochetPath: List<GridPos> = emptyList(),
    val eigenBarrier: EigenBarrier? = null,
    val combatLogs: List<CombatLogEntry> = emptyList(),
    val sectorId: Int = 1,
    val sectorTitle: String = "Sector 1: Coordinate Zero",
    val sectorObjective: String = "Defeat the Enemy Core Commander",
    val turnsRemaining: Int? = null,
    val statsSingularitiesTriggered: Int = 0,
    val statsEigenHits: Int = 0,
    val statsDamageDealt: Int = 0
) {
    val selectedUnit: TacticalUnit?
        get() = units.find { it.id == selectedUnitId }

    val playerUnits: List<TacticalUnit>
        get() = units.filter { it.faction == UnitFaction.PLAYER && it.isAlive }

    val enemyUnits: List<TacticalUnit>
        get() = units.filter { it.faction == UnitFaction.ENEMY_AI && it.isAlive }

    val playerCommander: TacticalUnit?
        get() = playerUnits.find { it.unitClass == UnitClass.COMMANDER }

    val enemyCommander: TacticalUnit?
        get() = enemyUnits.find { it.unitClass == UnitClass.COMMANDER }
}
